export type DailyQuote = (typeof HEALTH_QUOTES)[number]

/** Local day of the year, 1 through 366. February 29 is 60. */
export function dayOfYear(date: Date) {
  const start = Date.UTC(date.getFullYear(), 0, 1)
  const current = Date.UTC(date.getFullYear(), date.getMonth(), date.getDate())
  return Math.floor((current - start) / 86_400_000) + 1
}

function mulberry32(seed: number) {
  return () => {
    seed |= 0
    seed = (seed + 0x6d2b79f5) | 0
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** Stable shuffle so file order is not January-to-December. */
function dayOrder(length: number) {
  const order = Array.from({ length }, (_, index) => index)
  const random = mulberry32(0x594f5550)
  for (let index = length - 1; index > 0; index -= 1) {
    const swap = Math.floor(random() * (index + 1))
    const current = order[index]
    order[index] = order[swap]
    order[swap] = current
  }
  return order
}

const DAY_ORDER = dayOrder(HEALTH_QUOTES.length)

export function dailyQuote(date = new Date()): DailyQuote {
  const day = dayOfYear(date)
  return HEALTH_QUOTES[DAY_ORDER[day - 1]]
}
